                        remaining = need_visits - extra - 1
                        if remaining > 0:
                            moves += 2 * remaining
                else:
                    moves += 1
                    remaining = need_visits - extra - 1
                    if remaining > 0:
                        moves += 2 * remaining
                        extra = remaining
                    else:
                        extra = 0

                if moves > m:
                    return False

            return moves <= m

        lo, hi = 0, max(points) * m
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
